logic [2:0] count;
logic z_out;

always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
        count <= 3'b000;
        z_out <= 1'b0;
    end else begin
        current_state <= next_state;
        if (current_state == A) begin
            if (s) begin
                next_state <= B;
                count <= 3'b000;
            end else begin
                next_state <= A;
            end
        end else if (current_state == B) begin
            if (count < 3) begin
                next_state <= B;
                count <= count + 1;
            end else begin
                next_state <= C;
                count <= 3'b000;
            end
        end else if (current_state == C) begin
            if (count < 3) begin
                next_state <= C;
                count <= count + 1;
            end else begin
                next_state <= D;
                count <= 3'b000;
            end
        end else if (current_state == D) begin
            if (count < 3) begin
                next_state <= D;
                count <= count + 1;
            end else begin
                next_state <= E;
                count <= 3'b000;
            end
        end else if (current_state == E) begin
            next_state <= A;
        end
    end
end

always_comb begin
    case (current_state)
        A: next_state = (s) ? B : A;
        B: next_state = (count < 3) ? B : C;
        C: next_state = (count < 3) ? C : D;
        D: next_state = (count < 3) ? D : E;
        E: next_state = A;
        default: next_state = A;
    endcase
end

always_comb begin
    case (current_state)
        B: begin
            if (count == 2) begin
                z_out = (w == 1'b1) ? 1'b1 : 1'b0;
            end else begin
                z_out = 1'b0;
            end
        end
        C: begin
            if (count == 2) begin
                z_out = (w == 1'b1) ? 1'b1 : 1'b0;
            end else begin
                z_out = 1'b0;
            end
        end
        D: begin
            if (count == 2) begin
                z_out = (w == 1'b1) ? 1'b1 : 1'b0;
            end else begin
                z_out = 1'b0;
            end
        end
        E: z_out = 1'b0;
        default: z_out = 1'b0;
    endcase
end

assign z = z_out;

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the game
    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Internal signals for neighbor counting
    reg [255:0] neighbors;

    // Function to compute the number of live neighbors for a cell
    function [7:0] count_neighbors;
        input [7:0] row;
        input [7:0] col;
        begin
            count_neighbors = 0;
            for (int i = -1; i <= 1; i = i + 1) begin
                for (int j = -1; j <= 1; j = j + 1) begin
                    if (i == 0 && j == 0) continue;
                    int r = (row + i) % 16;
                    int c = (col + j) % 16;
                    if (current_q[(r * 16) + c]) count_neighbors = count_neighbors + 1;
                end
            end
        end
    endfunction

    // Compute the number of live neighbors for each cell
    always @(*) begin
        for (int i = 0; i < 16; i = i + 1) begin
            for (int j = 0; j < 16; j = j + 1) begin
                int r = i;
                int c = j;
                int neighbor_count = count_neighbors(r, c);
                if (neighbor_count == 0 || neighbor_count == 1) begin
                    next_q[(r * 16) + c] = 1'b0;
                end else if (neighbor_count == 2) begin
                    next_q[(r * 16) + c] = current_q[(r * 16) + c];
                end else if (neighbor_count == 3) begin
                    next_q[(r * 16) + c] = 1'b1;
                end else begin
                    next_q[(r * 16) + c] = 1'b0;
                end
            end
        end
    end

    // Load the initial state
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            current_q <= next_q;
        end
    end

    // Output the current state
    assign q = current_q;

endmodule

