    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'd0;
            prev_s <= 3'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Determine current sensor state
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        // Above s[2]
                        state <= 2'd3;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else begin
                        // Between s[2] and s[1]
                        state <= 2'd2;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end else begin
                    // Between s[1] and s[0]
                    state <= 2'd1;
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            end else begin
                // Below s[0]
                state <= 2'd0;
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Check if the previous level was lower than the current level
    always @(posedge clk) begin
        if (state == 2'd0 && prev_s == 3'd0) begin
            // No change, do nothing
        end else if (state == 2'd1 && prev_s == 3'd1) begin
            // No change, do nothing
        end else if (state == 2'd2 && prev_s == 3'd2) begin
            // No change, do nothing
        end else if (state == 2'd3 && prev_s == 3'd3) begin
            // No change, do nothing
        end else begin
            // Previous level was lower than current level
            dfr <= 1'b1;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                aaah <= 1'b0;
            end else if (dig == 1'b1 && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig == 1'b1 && current_state == WALK_RIGHT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                digging <= 1'b0;
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                if (bump_left && bump_right) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state and outputs
            current_state <= next_state;

            if (current_state == WALK_LEFT) begin
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (current_state == WALK_RIGHT) begin
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end else if (current_state == FALLING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end
        end
    end

endmodule
